import{_ as a,o as r,c as t,a6 as o}from"./chunks/framework.BBIckNDn.js";const u=JSON.parse('{"title":"関数型・データ指向・CQRS — クラス以外の視点","description":"","frontmatter":{"title":"関数型・データ指向・CQRS — クラス以外の視点","study":{"source":"設計の手帖","kind":"本文","status":"既存原稿","summary":"設計の知識が増えるほど、どこでもクラス階層を使う必要はなくなります。変わるものと制約に合う方法を選びます。"}},"headers":[],"relativePath":"design/notebook/paradigms.md","filePath":"design/notebook/paradigms.md"}'),i={name:"design/notebook/paradigms.md"};function n(s,e,l,d,p,c){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="関数型・データ指向・cqrs-—-クラス以外の視点" tabindex="-1">関数型・データ指向・CQRS — クラス以外の視点 <a class="header-anchor" href="#関数型・データ指向・cqrs-—-クラス以外の視点" aria-label="Permalink to &quot;関数型・データ指向・CQRS — クラス以外の視点&quot;">​</a></h1><p>設計の知識が増えるほど、どこでもクラス階層を使う必要はなくなります。変わるものと制約に合う方法を選びます。</p><p>05 · 視野を広げ、使ってみる / 関数型・データ指向・CQRS / Choose the right axis of change / 応用 / 10分</p><p>タグ: 関数型 / 純粋関数 / Data-Oriented / ECS / CQRS / モノリス</p><h2 id="関数型の発想-計算と副作用を分ける" tabindex="-1">関数型の発想：計算と副作用を分ける <a class="header-anchor" href="#関数型の発想-計算と副作用を分ける" aria-label="Permalink to &quot;関数型の発想：計算と副作用を分ける&quot;">​</a></h2><div><p>入力が同じなら同じ結果を返し、外部状態を変えない関数を純粋関数と呼びます。割引計算は純粋な関数、DB 保存や時刻取得は外側へ寄せると、計算のテストが簡単になります。C++ も C# も、オブジェクト指向とこの考え方を組み合わせられます。</p><p>たとえば <code>CalculateTotal(lines, policy)</code> が計算結果を返し、<code>PlaceOrderUseCase</code> が取得と保存を担当します。関数型とはすべてを LINQ やラムダで一行にすることではありません。副作用と状態変更を明示する視点が大切です。</p></div><h2 id="データ指向-処理とメモリの並びから考える" tabindex="-1">データ指向：処理とメモリの並びから考える <a class="header-anchor" href="#データ指向-処理とメモリの並びから考える" aria-label="Permalink to &quot;データ指向：処理とメモリの並びから考える&quot;">​</a></h2><div><p>大量の座標を毎フレーム更新するなら、オブジェクトごとの美しい階層より、連続したデータをまとめて処理する構造が重要になる場合があります。AoS（構造体の配列）と SoA（項目ごとの配列）は、その代表的な比較軸です。どちらが速いかはアクセスの仕方や環境で変わるため、計測します。</p><p><strong>ECS</strong> は Entity を識別子、Component をデータ、System を処理として組み立てる代表的な方式です。用語や実装はフレームワークごとに違い、ECS とデータ指向設計は同義ではありません。少数の注文を扱う業務アプリへ、性能上の理由なく導入する必要はありません。</p></div><h2 id="cqrs-更新と参照でモデルを分ける" tabindex="-1">CQRS：更新と参照でモデルを分ける <a class="header-anchor" href="#cqrs-更新と参照でモデルを分ける" aria-label="Permalink to &quot;CQRS：更新と参照でモデルを分ける&quot;">​</a></h2><div><p>注文の更新には厳しい不変条件が必要でも、一覧には顧客名と合計だけあれば足りるかもしれません。更新モデルと読み取りモデルを分けると、それぞれを目的に合わせられます。DB を必ず二つにする、イベントソーシングを必須にする、といった意味ではありません。</p><p>別の読み取りストアへ非同期反映するなら、表示に反映されるまでの遅れと、運用・再構築の複雑さが増えます。まず読み取り専用の Query と DTO を分ける程度で足りるかを検討します。</p></div><h2 id="モジュラーモノリスとマイクロサービス" tabindex="-1">モジュラーモノリスとマイクロサービス <a class="header-anchor" href="#モジュラーモノリスとマイクロサービス" aria-label="Permalink to &quot;モジュラーモノリスとマイクロサービス&quot;">​</a></h2><div><p>一つの配置単位の中でも、モジュール間の公開 API や依存を整理できます。マイクロサービスへ分けると独立した配置やスケールが可能になりますが、ネットワーク障害、データ整合性、監視などの設計が増えます。クラス分割の延長だけで選ばず、チームと運用の要件で判断します。</p><aside class="article-note"><strong>比較するときの軸</strong><p>変更頻度、データ量、性能、チームの境界、障害の扱い、運用負担。どの制約を解くための方式かを先に言葉にします。</p></aside></div><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><p>その抽象化は変更のためですか、性能のためですか。必要性をどう確かめますか？</p><h2 id="この章の参考資料" tabindex="-1">この章の参考資料 <a class="header-anchor" href="#この章の参考資料" aria-label="Permalink to &quot;この章の参考資料&quot;">​</a></h2><ul><li><a href="https://isocpp.github.io/CppCoreGuidelines/CppCoreGuidelines" target="_blank" rel="noreferrer">C++ Core Guidelines</a> — Bjarne Stroustrup / Herb Sutter ほか。インターフェース、所有権、クラス設計の指針。規格書そのものではありません。</li><li><a href="https://martinfowler.com/bliki/CQRS.html" target="_blank" rel="noreferrer">CQRS</a> — Martin Fowler。更新用と参照用のモデルを分ける考え方と、複雑性の注意点。</li><li><a href="https://learn.microsoft.com/en-us/dotnet/standard/modern-web-apps-azure-architecture/common-web-application-architectures" target="_blank" rel="noreferrer">Common web application architectures</a> — Microsoft Learn。レイヤーと、Application Core へ向ける依存関係。</li></ul><p><a href="/study/design/naming.html">クラス名辞典</a> / <a href="/study/design/pattern-index.html">パターン一覧</a> / <a href="/study/design/notebook-references.html">手帖の参考資料</a></p>',17)])])}const m=a(i,[["render",n]]);export{u as __pageData,m as default};
